{"edges": [
["a","b"],["a","c"],["a","d"],["a","e"],["a","f"],["a","g"],["a","h"],["a","i"],["a","j"],
["b","c"],["b","d"],["b","e"],["b","f"],["b","g"],["b","h"],["b","i"],["b","j"],
["c","d"],["c","e"],["c","f"],["c","g"],["c","h"],["c","i"],["c","j"],
["d","e"],["d","f"],["d","g"],["d","h"],["d","i"],["d","j"],
["e","f"],["e","g"],["e","h"],["e","i"],["e","j"],
["f","g"],["f","h"],["f","i"],["f","j"],
["g","h"],["g","i"],["g","j"],
["h","i"],["h","j"],
["i","j"]
]}
```
